// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame, ERC20Interface} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;

    function setUp() public { c = new PoCGame(address(this), 0); }

    function testFuzz_property(uint256 tokens, address tokenOwner) public {
        // setUp deployer is address(this), which is the owner of c -> calls from here pass onlyOwner.
        GoodERC20 token = new GoodERC20(); // its transfer always succeeds and returns true
        tokens = bound(tokens, 0, 1e30);

        bool returned;
        try c.transferAnyERC20Token(address(token), tokenOwner, tokens) returns (bool s) {
            returned = s;
        } catch {
            returned = false;
        }

        // General rule: the function must relay the token's transfer result.
        // Since GoodERC20.transfer always returns true, the reference returns true;
        // the mutant returns the default false and breaks the rule for every input.
        assertTrue(returned, "transferAnyERC20Token must return the token transfer result");
    }
}

contract GoodERC20 is ERC20Interface {
    function transfer(address to, uint256 tokens) virtual override public returns (bool success) {
        return true;
    }
}
